import json,pathlib
from run import R
for app in ['web','admin']:
 root=R/'workspace'/app
 for d in ['src/server','app','fixtures']:(root/d).mkdir(parents=True,exist_ok=True)
 (root/'eslint.config.mjs').write_text("import { createConfig } from '../lint-config.mjs';\nexport default createConfig(import.meta.dirname);\n")
 ts={'compilerOptions':{'target':'ES2023','lib':['ES2024','DOM','DOM.Iterable'],'module':'ESNext','moduleResolution':'Bundler','jsx':'react-jsx','strict':True,'skipLibCheck':False,'noEmit':True,'esModuleInterop':True,'resolveJsonModule':True,'baseUrl':'.','paths':{'@/*':['./src/*']},'types':['node']},'include':['app/**/*.tsx','src/**/*.ts','src/**/*.tsx']}
 # TS 6 no longer needs baseUrl for explicit relative paths.
 ts['compilerOptions'].pop('baseUrl')
 (root/'tsconfig.json').write_text(json.dumps(ts,indent=2)+'\n')
 (root/'src/values.ts').write_text(f"export const marker = 'synthetic-{app}';\n")
 (root/'src/server/only.ts').write_text("export const syntheticServerMarker = 'not-a-secret';\n")
 (root/'src/controls.tsx').write_text('''"use client";
import { useState, type ComponentProps } from 'react';
export function ProbeButton(props: ComponentProps<'button'>) { return <button type="button" {...props} />; }
export function ProbeInput(props: ComponentProps<'input'>) { return <input {...props} />; }
export function Controls() {
  const [count, setCount] = useState(0);
  return <section aria-label="Synthetic controls">
    <ProbeInput aria-label="Synthetic title" defaultValue="Example" />
    <ProbeButton onClick={() => setCount(count + 1)}>Increment</ProbeButton>
    <output aria-live="polite">{count}</output>
  </section>;
}
''')
 (root/'src/error-boundary.tsx').write_text('''"use client";
import { Component, type ReactNode } from 'react';
export class ProbeBoundary extends Component<{ children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  render() { return this.state.failed ? <p role="alert">Synthetic failure</p> : this.props.children; }
}
''')
 (root/'app/page.tsx').write_text('''import { Controls } from '@/controls';
import { ProbeBoundary } from '@/error-boundary';
import { marker } from '@/values';
export default function Page() {
  return <main><h1>{marker}</h1><ProbeBoundary><Controls /></ProbeBoundary></main>;
}
''')
 (root/'app/layout.tsx').write_text('''import type { ReactNode } from 'react';
export default function Layout({ children }: { children: ReactNode }) {
  return <html lang="en"><body>{children}</body></html>;
}
''')
 (root/'probe-settings.js').write_text("export const probeSettings = Object.freeze({ synthetic: true });\n")
print('Created two separate synthetic compositions, owned controls/error boundary, TS and lint configs.')

import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { ESLint } from 'eslint';
import nextPlugin from '@next/eslint-plugin-next';
import hooks from 'eslint-plugin-react-hooks';
import a11y from 'eslint-plugin-jsx-a11y';
const root = path.dirname(import.meta.dirname);
const baseline = JSON.parse(fs.readFileSync('$LINT_RESEARCH_ROOT/static-results.json', 'utf8'));
const require = createRequire(import.meta.url);
const nr = createRequire(require.resolve('eslint-config-next'));
const identities = {};
for (const [name, version] of Object.entries({'eslint':'10.13.0','eslint-config-next':'16.4.2','eslint-plugin-react':'7.37.5','eslint-plugin-import':'2.32.0','eslint-plugin-jsx-a11y':'6.10.2','eslint-plugin-react-hooks':'7.1.1','@next/eslint-plugin-next':'16.4.2','typescript-eslint':'8.72.0'})) {
  const resolved = name === 'eslint-config-next' ? require.resolve(name + '/package.json') : nr.resolve(name + '/package.json');
  const actual = JSON.parse(fs.readFileSync(resolved, 'utf8')).version;
  assert.equal(actual, version, name); identities[name] = {version: actual, path: resolved};
}
const level = value => Array.isArray(value) ? level(value[0]) : value === 'error' ? 2 : value === 'warn' ? 1 : value === 'off' ? 0 : value;
const results = [];
for (const app of ['web','admin']) {
 const cwd = path.join(import.meta.dirname, app); const lint = new ESLint({cwd});
 for (const extension of ['js','jsx','ts','tsx']) {
  const file = path.join(cwd, 'fixtures', 'effective.' + extension);
  const config = await lint.calculateConfigForFile(file); assert(config && !await lint.isPathIgnored(file));
  for (const name of baseline.react.active_in_next) assert.equal(level(config.rules['react/'+name]), 2, name);
  for (const [name,value] of Object.entries(nextPlugin.configs['core-web-vitals'].rules)) assert(level(config.rules[name]) >= level(value), name);
  for (const [name,value] of Object.entries(hooks.configs.recommended.rules)) assert(level(config.rules[name]) >= level(value), name);
  for (const name of baseline.a11y.configs.strictRules.active_error_rules) assert.equal(level(config.rules['jsx-a11y/'+name]), 2, name);
  assert.equal(level(config.rules['jsx-a11y/control-has-associated-label']),2);
  assert.equal(level(config.rules['jsx-a11y/no-aria-hidden-on-focusable']),2);
  const save={app,extension,parser:config.languageOptions.parser.meta,rules:config.rules,settings:config.settings,plugins:Object.keys(config.plugins)};
  fs.writeFileSync(path.join(root,'evidence',`effective-${app}-${extension}.json`),JSON.stringify(save,null,2));
  results.push({app,extension,reactEntries:17,nextRules:Object.keys(nextPlugin.configs['core-web-vitals'].rules).length,hooksRules:Object.keys(hooks.configs.recommended.rules).length,a11yBaseline:31});
 }
}
const loadedNative = Object.keys(require.cache).filter(p => /\.(node|wasm)$/.test(p));
fs.writeFileSync(path.join(root,'evidence/effective-summary.json'),JSON.stringify({identities,results,loadedNative},null,2));
console.log(JSON.stringify({identities,results,loadedNative},null,2));

