import type { ReactNode } from 'react';
export default function Layout({ children }: { children: ReactNode }) {
  return <html lang="en"><body>{children}</body></html>;
}

import { Controls } from '@/controls';
import { ProbeBoundary } from '@/error-boundary';
import { marker } from '@/values';
export default function Page() {
  return <main><h1>{marker}</h1><ProbeBoundary><Controls /></ProbeBoundary></main>;
}

{
  "name": "isolated-lint-web",
  "version": "0.0.0",
  "private": true,
  "dependencies": {
    "next": "16.4.2",
    "react": "19.3.1",
    "react-dom": "19.3.1"
  }
}

"use client";
import { useState, type ComponentProps } from 'react';
export function ProbeButton(props: ComponentProps<'button'>) { return <button type="button" {...props} />; }
export function ProbeInput(props: ComponentProps<'input'>) { return <input {...props} />; }
export function Controls() {
  const [count, setCount] = useState(0);
  return <section aria-label="Synthetic controls">
    <ProbeInput aria-label="Synthetic title" defaultValue="Example" />
    <ProbeButton onClick={() => setCount(count + 1)}>Increment</ProbeButton>
    <output aria-live="polite">{count}</output>
  </section>;
}

"use client";
import { Component, type ReactNode } from 'react';
export class ProbeBoundary extends Component<{ children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  render() { return this.state.failed ? <p role="alert">Synthetic failure</p> : this.props.children; }
}

